import itertools

def autocorr(seq):
    n = len(seq)
    C = {}
    for k in range(1, n):
        s = 0
        for i in range(n - k):
            s += seq[i] * seq[i + k]
        C[k] = s
    return C

n = 13
seq_fixed = {8: 1, 10: -1}
valid = []
for bits in itertools.product([-1, 1], repeat=n):
    seq = list(bits)
    # apply fixed assignments
    if seq[8] != 1 or seq[10] != -1:
        continue
    C = autocorr(seq)
    if C[4] == 2 and C[5] == -1:
        total = sum(C[k]**2 for k in range(1, n))
        if total <= 28:
            valid.append((seq, C, total))

print("found valid sequences:", len(valid))
if valid:
    for seq, C, total in valid[:5]:
        print(seq, total, C)

